'use client'

import { createContext, useContext, useEffect, useMemo, useState } from 'react'

export const WHOLESALE_MINIMUM_QUANTITY = 15
export type OrderMode = 'retail' | 'wholesale'
export type Product = { id: string; name: string; category: string; price: number; wholesalePrice: number | null; wholesaleMinimum?: number; unit: string; accent: string; stock: number | null; image?: string; description?: string; active?: boolean; showRetailPrice?: boolean }
export type CartLine = Product & { quantity: number; quality: string; orderMode: OrderMode }
type CartContextValue = { items: CartLine[]; products: Product[]; addItem: (product: Product, quantity?: number, orderMode?: OrderMode) => void; updateQuantity: (id: string, quantity: number, orderMode?: OrderMode) => void; updateQuality: (id: string, quality: string, orderMode?: OrderMode) => void; updateProduct: (id: string, updates: Omit<Product, 'id'>) => void; addProduct: (product: Product) => void; removeProduct: (id: string) => void; removeItem: (id: string, orderMode?: OrderMode) => void; count: number; total: number }
const CartContext = createContext<CartContextValue | null>(null)

export const getWholesaleMinimum = (product: Product) => product.wholesaleMinimum ?? WHOLESALE_MINIMUM_QUANTITY
export const getUnitPrice = (product: Product, quantity: number) =>
  product.wholesalePrice !== null && quantity >= getWholesaleMinimum(product) ? product.wholesalePrice : product.price

export function CartProvider({ children }: { children: React.ReactNode }) {
  const [items, setItems] = useState<CartLine[]>([])
  const [products, setProducts] = useState<Product[]>(catalog)
  const [itemsLoaded, setItemsLoaded] = useState(false)
  useEffect(() => {
    const saved = window.localStorage.getItem('muhoro-cart')
    if (saved) {
      const savedItems = JSON.parse(saved) as Array<Partial<CartLine> & Product>
      setItems(savedItems.map(item => ({ ...item, wholesalePrice: item.wholesalePrice ?? null, quality: item.quality ?? 'As listed', orderMode: item.orderMode ?? 'retail', quantity: item.quantity ?? 1 } as CartLine)))
    }
    const savedProducts = window.localStorage.getItem('muhoro-products')
    if (savedProducts) {
      const savedCatalog = JSON.parse(savedProducts) as Array<Partial<Product> & Pick<Product, 'id' | 'name' | 'category' | 'price' | 'unit' | 'accent' | 'stock'>>
      const savedById = new Map(savedCatalog.map(product => [product.id, product]))
      const updatedCatalog = catalog.map(product => ({ ...product, ...savedById.get(product.id), active: savedById.get(product.id)?.active ?? product.active ?? true, showRetailPrice: savedById.get(product.id)?.showRetailPrice ?? product.showRetailPrice ?? true }))
      const customProducts = savedCatalog
        .filter(product => product.id.startsWith('product-') && !catalog.some(item => item.id === product.id))
        .map(product => ({ ...product, wholesalePrice: product.wholesalePrice ?? null, active: product.active ?? true, showRetailPrice: product.showRetailPrice ?? true }) as Product)
      setProducts([...updatedCatalog, ...customProducts])
    }
    setItemsLoaded(true)
  }, [])
  useEffect(() => {
    if (itemsLoaded) {
      window.localStorage.setItem('muhoro-cart', JSON.stringify(items))
      window.localStorage.setItem('muhoro-products', JSON.stringify(products))
    }
  }, [items, itemsLoaded, products])
  const value = useMemo(() => ({
    items,
    products,
    addItem: (product: Product, quantity = 1, orderMode: OrderMode = 'retail') => setItems(current => {
      const requestedQuantity = orderMode === 'wholesale' ? Math.max(quantity, getWholesaleMinimum(product)) : quantity
      const found = current.find(item => item.id === product.id && item.orderMode === orderMode)
      return found ? current.map(item => item.id === product.id && item.orderMode === orderMode ? { ...item, ...product, quantity: item.quantity + requestedQuantity } : item) : [...current, { ...product, quantity: requestedQuantity, quality: 'As listed', orderMode }]
    }),
    updateQuantity: (id: string, quantity: number, orderMode: OrderMode = 'retail') => setItems(current => quantity > 0 ? current.map(item => item.id === id && item.orderMode === orderMode ? { ...item, quantity: orderMode === 'wholesale' ? Math.max(quantity, getWholesaleMinimum(item)) : quantity } : item) : current.filter(item => !(item.id === id && item.orderMode === orderMode))),
    updateQuality: (id: string, quality: string, orderMode: OrderMode = 'retail') => setItems(current => current.map(item => item.id === id && item.orderMode === orderMode ? { ...item, quality } : item)),
    updateProduct: (id: string, updates: Omit<Product, 'id'>) => {
      setProducts(current => current.map(product => product.id === id ? { ...product, ...updates } : product))
      setItems(current => current.map(item => item.id === id ? { ...item, ...updates } : item))
    },
    addProduct: (product: Product) => setProducts(current => [...current, { ...product, active: product.active ?? true, showRetailPrice: product.showRetailPrice ?? true }]),
    removeProduct: (id: string) => {
      setProducts(current => current.filter(product => product.id !== id))
      setItems(current => current.filter(item => item.id !== id))
    },
    removeItem: (id: string, orderMode: OrderMode = 'retail') => setItems(current => current.filter(item => !(item.id === id && item.orderMode === orderMode))),
    count: items.reduce((sum, item) => sum + item.quantity, 0),
    total: items.reduce((sum, item) => sum + item.quantity * getUnitPrice(item, item.quantity), 0),
  }), [items, products])
  return <CartContext.Provider value={value}>{children}</CartContext.Provider>
}
export function useCart() { const context = useContext(CartContext); if (!context) throw new Error('useCart must be used inside CartProvider'); return context }

